cd /home/admin/backend && php artisan tinker --execute="
use App\Models\Student;
use Illuminate\Support\Facades\DB;

\$branchId = 22;
\$spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load('/home/admin/敦化分校學生名單.xlsx');
\$sheet = \$spreadsheet->getActiveSheet();
\$rows = \$sheet->toArray(null, true, true, false);

\$gradeMap = [
    '小一'=>'P1','小二'=>'P2','小三'=>'P3','小四'=>'P4','小五'=>'P5','小六'=>'P6',
    '小1'=>'P1','小2'=>'P2','小3'=>'P3','小4'=>'P4','小5'=>'P5','小6'=>'P6',
    '國一'=>'J1','國二'=>'J2','國三'=>'J3',
    '國1'=>'J1','國2'=>'J2','國3'=>'J3',
    '高一'=>'H1','高二'=>'H2','高三'=>'H3',
    '高1'=>'H1','高2'=>'H2','高3'=>'H3',
];
\$classIdMap = [
    'P1'=>1,'P2'=>2,'P3'=>3,'P4'=>4,'P5'=>5,'P6'=>6,
    'J1'=>7,'J2'=>8,'J3'=>9,
    'H1'=>10,'H2'=>11,'H3'=>12,
];

\$skipNames = ['姓名','學生','name','國小','國中','高中'];
\$created = 0; \$updated = 0; \$skipped = 0;

foreach (\$rows as \$row) {
    \$name = trim((string)(\$row[0] ?? ''));
    if (\$name === '' || in_array(\$name, \$skipNames, true)) { \$skipped++; continue; }

    \$school = trim((string)(\$row[1] ?? ''));
    \$gradeRaw = trim((string)(\$row[2] ?? ''));
    \$grade = \$gradeMap[\$gradeRaw] ?? null;
    \$classId = \$grade ? (\$classIdMap[\$grade] ?? 7) : 7;

    \$existing = Student::where('CampusID', \$branchId)->where('name', \$name)->first();
    if (\$existing) {
        \$changed = false;
        if (\$school !== '' && (\$existing->SchoolName ?? '') !== \$school) { \$existing->SchoolName = \$school; \$changed = true; }
        if (\$grade && (int)\$existing->ClassID !== \$classId) { \$existing->ClassID = \$classId; \$changed = true; }
        if ((\$existing->status ?? '') !== 'active') { \$existing->status = 'active'; \$changed = true; }
        if (\$changed) { \$existing->save(); \$updated++; echo '更新: ' . \$name . PHP_EOL; }
        else { \$skipped++; }
        continue;
    }

    Student::create([
        'name' => \$name,
        'CampusID' => \$branchId,
        'ClassID' => \$classId,
        'SchoolName' => \$school !== '' ? \$school : null,
        'Phone' => null,
        'status' => 'active',
        'enable' => 1,
        'MDT' => now(),
        'TelegramID' => '',
        'Notify_Token' => '',
    ]);
    \$created++;
    echo '新增: ' . \$name . ' (' . \$gradeRaw . ')' . PHP_EOL;
}

echo PHP_EOL . '=== 完成 ===' . PHP_EOL;
echo '新增: ' . \$created . ' 筆' . PHP_EOL;
echo '更新: ' . \$updated . ' 筆' . PHP_EOL;
echo '略過: ' . \$skipped . ' 筆' . PHP_EOL;
"
